        return new int[0][0];
    }

    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        int r = sc.nextInt(), c = sc.nextInt();
        int[][] grid = new int[r][c];
        for (int i = 0; i < r; i++) {
            String s = sc.next();
            for (int j = 0; j < c; j++) grid[i][j] = s.charAt(j) - '0';
        }
        int[][] res = highestPeak(grid);
        StringBuilder sb = new StringBuilder();
        for (int[] row : res) {
            for (int j = 0; j < row.length; j++) sb.append(row[j]).append(j + 1 < row.length ? " " : "\n");
        }
        System.out.print(sb);
    }
}
